var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ShopDb>(o => o.UseSqlite("Data Source=summary.db"));
var app = builder.Build();

using (var scope = app.Services.CreateScope())
    scope.ServiceProvider.GetRequiredService<ShopDb>().Database.EnsureCreated();

app.MapPost("/customers", async (Customer c, ShopDb db, CancellationToken ct) =>
{
    db.Customers.Add(c);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/customers/{c.Id}", new { c.Id, c.Name });
});

app.MapPost("/orders", async (Order o, ShopDb db, CancellationToken ct) =>
{
    db.Orders.Add(o);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/orders/{o.Id}", new { o.Id });
});

// The slow one: one query for the customers, then one per customer.
app.MapGet("/customers/summary", async (ShopDb db, CancellationToken ct) =>
{
    var customers = await db.Customers.AsNoTracking().OrderBy(c => c.Name).ToListAsync(ct);
    var result = new List<CustomerSummary>();
    foreach (var c in customers)
    {
        var orders = await db.Orders.AsNoTracking().Where(o => o.CustomerId == c.Id).ToListAsync(ct);
        result.Add(new CustomerSummary(c.Name, orders.Count, orders.Sum(o => o.TotalCents)));
    }
    return result;
});

app.Run();

record CustomerSummary(string Name, int Orders, int TotalCents);

class Customer
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public List<Order> Orders { get; set; } = [];
}

class Order
{
    public int Id { get; set; }
    public int CustomerId { get; set; }
    public int TotalCents { get; set; }
}

class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<Order> Orders => Set<Order>();
}

